typedef struct { time_t from; double amount; } rate_t;   /* sorted by from */

int rate_at(const rate_t *h, size_t n, time_t when, double *out) {
    size_t lo = 0, hi = n;                   /* first index whose from > when */
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (h[mid].from <= when) lo = mid + 1; else hi = mid;
    }
    if (lo == 0) return 0;                   /* no version in force on `when` */
    *out = h[lo - 1].amount;                 /* latest milestone <= when */
    return 1;
}
